(() => {
  'use strict';
  if (!/\/apps\/fase-a\//i.test(location.pathname)) return;

  const params = new URLSearchParams(location.search);
  const grade = String(params.get('grade') || '').trim().toUpperCase();
  if (grade !== 'I') return;

  const VERSION = '20260909-cute-cover-1';
  const COVER_IMAGE = 'data:image/webp;base64,';
  const style = document.createElement('style');
  style.id = 'ep-grade-one-cover-style';
  style.textContent = `
    .page.cover[data-ep-grade-one-cover="1"] {
      background-color: #eefaff !important;
      background-image: url("${COVER_IMAGE}") !important;
      background-position: center center !important;
      background-repeat: no-repeat !important;
      background-size: cover !important;
    }
    .page.cover[data-ep-grade-one-cover="1"] .page-inner,
    .page.cover[data-ep-grade-one-cover="1"] .cover-content {
      position: relative;
      z-index: 1;
    }
    .page.cover[data-ep-grade-one-cover="1"] .cover-center {
      background: rgba(255,255,255,.82);
      border: 1px solid rgba(74,169,208,.28);
      border-radius: 8mm;
      box-shadow: 0 5mm 13mm rgba(40,119,154,.14);
      padding: 10mm 9mm;
    }
  `;
  (document.head || document.documentElement).appendChild(style);

  function applyCover(cover) {
    if (!(cover instanceof HTMLElement)) return;
    const text = String(cover.textContent || '');
    if (!/Kelas\s+I(?:\s|·|\/|$)/i.test(text) || !/Fase\s+A/i.test(text)) return;
    cover.dataset.epGradeOneCover = '1';
  }

  function applyAll(root = document) {
    if (root.matches?.('.page.cover')) applyCover(root);
    root.querySelectorAll?.('.page.cover').forEach(applyCover);
  }

  applyAll();
  new MutationObserver(records => {
    for (const record of records) {
      for (const node of record.addedNodes) {
        if (node.nodeType === Node.ELEMENT_NODE) applyAll(node);
      }
    }
  }).observe(document.documentElement, {subtree: true, childList: true});

  window.addEventListener('load', () => applyAll());
})();
